// Renders the state machine reference (shared by the script and the tests).

function edges(machine) {
  const rows = []
  for (const name of machine.stateNames) {
    for (const [event, t] of Object.entries(machine.states[name].on || {})) {
      rows.push({ from: name, event, to: typeof t === 'string' ? t : t.target })
    }
  }
  return rows
}

export function renderMachinesDoc(machines) {
  const lines = [
    '# State machines',
    '',
    '<!-- Generated by `npm run docs:machines` from src/machines. Do not edit by hand. -->',
    '',
    'Every multi-step flow in Gen Arcade is a small state machine in `src/machines/`.',
    'Components run them with `useMachine` (src/hooks/useMachine.js) and put',
    '`data-machine` and `data-state` on their root element. An event that the current',
    'state does not list is ignored, so impossible steps cannot happen.',
    '',
    '| Machine | States | Description |',
    '|---|---|---|',
    ...machines.map((m) => `| [\`${m.id}\`](#${m.id}) | ${m.stateNames.length} | ${m.description} |`),
    '',
  ]
  for (const m of machines) {
    lines.push(`## ${m.id}`, '', m.description, '', '```mermaid', 'stateDiagram-v2', `  [*] --> ${m.initial}`)
    for (const e of edges(m)) lines.push(`  ${e.from} --> ${e.to}: ${e.event}`)
    for (const name of m.stateNames) if (m.states[name].final) lines.push(`  ${name} --> [*]`)
    lines.push('```', '')
    const globals = Object.entries(m.on)
    if (globals.length) {
      lines.push(`From any state: ${globals.map(([e, t]) => `\`${e}\` goes to \`${typeof t === 'string' ? t : t.target}\``).join(', ')}.`, '')
    }
    lines.push('| State | Meaning | Events |', '|---|---|---|')
    for (const name of m.stateNames) {
      const s = m.states[name]
      const ev = Object.entries(s.on || {}).map(([e, t]) => `\`${e}\` to \`${typeof t === 'string' ? t : t.target}\``).join(', ')
      lines.push(`| \`${name}\`${name === m.initial ? ' (start)' : ''}${s.final ? ' (end)' : ''} | ${s.description || ''} | ${ev || 'none'} |`)
    }
    lines.push('')
  }
  return lines.join('\n')
}
